        contextRight: "对，LHC是同步加速器。同步加速器的特点是磁场强度会随着粒子能量增加而同步增加，这样粒子就能一直保持在同一个轨道上运动。LHC的周长是27公里，足够大，让质子能在里面转圈，每转一圈加速一点，积累能量达到很高的能量。你想想，你骑扫帚在环形跑道上飞，圈越小转弯越急——LHC设计成这么大，就是为了减少粒子转弯时的能量损失，同时能加速到非常高的能量。我以前在麻瓜那边看新闻，LHC的隧道比地铁隧道还大，造价上百亿瑞士法郎。记住：LHC是同步加速器，周长27公里。",
